#[derive(Clone, Copy)]
struct DragScrolling {
    /// Where the pointer is.
    at: Point<Pixels>,
    /// When the area was last scrolled, while it goes on scrolling.
    scrolled: Option<Instant>,
}

impl DragScroll {
